const $=s=>document.querySelector(s);const canvas=$('#canvas'),ctx=canvas.getContext('2d');let color='#155c50',erase=false,drawing=false,current=[],strokes=[],redo=[],guide='',odia=false;
try{const saved=JSON.parse(localStorage.getItem('odia-board')||'{}');strokes=saved.strokes||[];guide=saved.guide||''}catch{}
function persist(){try{localStorage.setItem('odia-board',JSON.stringify({strokes,guide}));$('#boardnote').textContent='Your board is saved on this device.'}catch{$('#boardnote').textContent='Storage unavailable. Save an image to keep your work.'}}
function render(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=r.width*d;canvas.height=r.height*d;ctx.scale(d,d);ctx.clearRect(0,0,r.width,r.height);if(guide){ctx.fillStyle='#dfe8da';ctx.font=`${Math.min(r.height*.6,r.width*.5)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(guide,r.width/2,r.height/2)}for(const s of strokes.concat(current.length?[{points:current,color:erase?'#fffef9':color,size:+$('#size').value*(erase?5:1)}]:[])){ctx.beginPath();ctx.lineCap=ctx.lineJoin='round';ctx.strokeStyle=s.color;ctx.lineWidth=s.size;const p=s.points;ctx.moveTo(p[0][0]*r.width,p[0][1]*r.height);if(p.length===1)ctx.lineTo(p[0][0]*r.width+.1,p[0][1]*r.height);for(const q of p.slice(1))ctx.lineTo(q[0]*r.width,q[1]*r.height);ctx.stroke()}}
function point(e){const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]}
canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);current=[point(e)];render()};canvas.onpointermove=e=>{if(drawing){current.push(point(e));render()}};function finish(){if(!drawing)return;drawing=false;strokes.push({points:current,color:erase?'#fffef9':color,size:+$('#size').value*(erase?5:1)});current=[];persist();render()}canvas.onpointerup=finish;canvas.onpointercancel=finish;new ResizeObserver(render).observe(canvas);
for(const c of ['#155c50','#242d3a','#d25343','#d49d24','#4877c3','#9665b1']){const b=document.createElement('button');b.style.background=c;b.setAttribute('aria-label','Use color '+c);b.onclick=()=>{color=c;$('#pen').click()};$('.colors').append(b)}
$('#pen').onclick=()=>{erase=false;$('#pen').classList.add('active');$('#eraser').classList.remove('active')};$('#eraser').onclick=()=>{erase=true;$('#eraser').classList.add('active');$('#pen').classList.remove('active')};$('#undo').onclick=()=>{strokes.pop();persist();render()};$('#clear').onclick=()=>{if((strokes.length||guide)&&confirm('Clear this board? You can save an image first.')){strokes=[];guide='';persist();render()}};
$('#save').onclick=()=>{const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;const c=out.getContext('2d');c.fillStyle='#fffef9';c.fillRect(0,0,out.width,out.height);c.drawImage(canvas,0,0);const a=document.createElement('a');a.download='odia-smart-lab-board.png';a.href=out.toDataURL();a.click()};
function tab(name){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==name));document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));if(name==='whiteboard')render()}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
const vowels=['ଅ','ଆ','ଇ','ଈ','ଉ','ଊ','ଋ','ଏ','ଐ','ଓ','ଔ'];const sounds=['a','aa','i','ee','u','oo','ru','e','ai','o','au'];function practice(letter){if(strokes.length&&!confirm('Start a fresh practice board? Save your drawing first if needed.'))return;guide=letter;strokes=[];persist();tab('whiteboard');$('#boardtitle').textContent='Trace the letter: '+letter}vowels.forEach((v,i)=>{const b=document.createElement('button');b.innerHTML=v+'<small>'+sounds[i]+'</small>';b.onclick=()=>practice(v);$('#letters').append(b)});
const lessons=[['01 · LANGUAGE','Odia vowels','ଅ ଆ ଇ','Explore the first three vowels and practice their shapes.','Practice ଅ',()=>practice('ଅ')],['02 · NUMBERS','Count with Odia','୧ ୨ ୩','Learn the digits from one to five: ୧ ୨ ୩ ୪ ୫.','Practice ୧',()=>practice('୧')],['03 · CLASS ACTIVITY','Test your knowledge','✦','Identify Odia letters and numbers in a short classroom quiz.','Start quiz',()=>{restart();tab('quiz')}]];for(const [tag,title,glyph,desc,label,action]of lessons){const c=document.createElement('article');c.className='card';c.innerHTML=`<span class="tag">${tag}</span><h2>${title}</h2><div class="glyph">${glyph}</div><p>${desc}</p><button>${label} →</button>`;c.querySelector('button').onclick=action;$('#lessonCards').append(c)}
const questions=[['Which letter makes the “aa” sound?',['ଅ','ଆ','ଇ','ଉ'],1],['Which Odia digit means three?',['୧','୫','୩','୨'],2],['Which letter makes the “i” sound?',['ଓ','ଏ','ଉ','ଇ'],3],['Which Odia digit means five?',['୫','୪','୨','୧'],0]];let qi=0,score=0;function showQ(){$('#progress').textContent=`Question ${qi+1} of ${questions.length} · Score ${score}`;$('#question').textContent=questions[qi][0];$('#feedback').textContent='';$('#next').classList.add('hidden');$('#answers').replaceChildren();questions[qi][1].forEach((a,i)=>{const b=document.createElement('button');b.textContent=a;b.onclick=()=>{const correct=i===questions[qi][2];if(correct)score++;$('#feedback').textContent=correct?'Correct! Well done.':'The correct answer is '+questions[qi][1][questions[qi][2]]+'. Keep learning!';$('#answers').querySelectorAll('button').forEach(x=>x.disabled=true);$('#next').classList.remove('hidden')};$('#answers').append(b)})}function restart(){qi=0;score=0;showQ()}$('#restart').onclick=restart;$('#next').onclick=()=>{qi++;if(qi<questions.length)showQ();else{$('#progress').textContent='Quiz complete';$('#question').textContent=`You scored ${score} out of ${questions.length}!`;$('#answers').replaceChildren();$('#feedback').textContent='Practice makes progress. Try again whenever you’re ready.';$('#next').classList.add('hidden')}};restart();
$('#language').onclick=()=>{odia=!odia;document.documentElement.lang=odia?'or':'en';$('#heading').textContent=odia?'ଆସନ୍ତୁ ଏକାଠି ଶିଖିବା।':'Let’s learn something wonderful.';$('#subtitle').textContent=odia?'ଲେଖନ୍ତୁ, ଶିଖନ୍ତୁ ଏବଂ ଅଭ୍ୟାସ କରନ୍ତୁ।':'Draw, explore, and bring every lesson to life.';['ହ୍ୱାଇଟବୋର୍ଡ','ଓଡ଼ିଆ ବର୍ଣ୍ଣମାଳା','ପାଠ','ପ୍ରଶ୍ନୋତ୍ତର'].forEach((t,i)=>document.querySelectorAll('[data-tab]')[i].textContent=odia?t:['✎ Whiteboard','ଅ Odia alphabet','▤ Lessons','✦ Quick quiz'][i]);$('#status').textContent=odia?'ଓଡ଼ିଆ ନାଭିଗେସନ୍ · Lesson instructions are in English.':''};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('#status').textContent='Full screen is unavailable in this browser.'}};if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
